// Build list for blocked_email_domains.
// upstream (lowercase, trimmed, no blanks/comments) + EXTRAS - EXCLUDE - SAFE,
// valid hostnames only, de-duplicated, sorted, joined with '|'.
// Throws (so nothing is written; wire an error workflow to get alerted) if the download looks wrong.
var MIN_UPSTREAM = 5000;
var MAX_BYTES = 2048 * 1024;   // must match "Max response size (KB)" on the fetch node

// Optional domains you want blocked on top of upstream. Example:
// var EXTRAS = ['typo-domain.example', 'another.example'];
var EXTRAS = [];

// Never block these, even if upstream lists them (privacy alias services).
var EXCLUDE = ['simplelogin.com', 'passmail.net'];

// Major providers — never block, even if upstream lists them.
var SAFE = ['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com', 'icloud.com', 'me.com',
  'proton.me', 'protonmail.com', 'aol.com', 'gmx.com', 'zoho.com', 'yandex.com'];
var OK = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/;

var src = $input.all()[0].json || {};
var body = src.data;
if (typeof body !== 'string') throw new Error('Upstream download was not plain text');
if (body.length >= MAX_BYTES) throw new Error('Upstream download hit the size cap (' + body.length + ' bytes), probably truncated; nothing written');
var up = {}, upCount = 0;
body.split(/\r\n|[\n\r\v\f\x1c\x1d\x1e\x85\u2028\u2029]/).forEach(function (l) {
  var t = l.trim();
  if (!t || l.charAt(0) === '#') return;
  upCount++; up[t.toLowerCase()] = 1;
});
if (upCount < MIN_UPSTREAM) throw new Error('Upstream list suspiciously small (' + upCount + ' entries); nothing written');
EXTRAS.forEach(function (d) { up[d] = 1; });
EXCLUDE.forEach(function (d) { delete up[d]; });
var guarded = [], bad = [], want = [];
SAFE.forEach(function (d) { if (up[d]) { guarded.push(d); delete up[d]; } });
Object.keys(up).forEach(function (d) { if (OK.test(d)) want.push(d); else bad.push(d); });
want.sort();
var curRaw = String($site_settings.blocked_email_domains || '');
var parts = curRaw.split('|'), cur = {}, clean = true;
parts.forEach(function (x) { var t = x.trim(); if (t !== x) clean = false; if (t) cur[t.toLowerCase()] = 1; });
var wantSet = {}; want.forEach(function (d) { wantSet[d] = 1; });
var added = want.filter(function (d) { return !cur[d]; });
var removed = Object.keys(cur).filter(function (d) { return !wantSet[d]; }).sort();
var changed = (added.length || removed.length || !clean) ? 1 : 0;
return [{ json: {
  changed: changed, value: want.join('|'), total: want.length, before: Object.keys(cur).length,
  upstream: upCount, added: added.length, removed: removed.length, was_clean: clean,
  added_sample: added.slice(0, 10), removed_sample: removed.slice(0, 10),
  invalid_skipped: bad.slice(0, 20), guarded_major_providers: guarded
} }];

// Verify. Reads the setting value the Site setting step saved and compares it with what Build list produced.
var saved = $input.all()[0].json || {};
var b = $('Build list').first().json;
if (saved.value !== b.value) throw new Error('Verify failed: saved blocked_email_domains differs from the built list (' + String(saved.value || '').split('|').length + ' vs ' + b.total + ')');
var msg = '🧹 Blocked email domains synced: +' + b.added + ' added, −' + b.removed + ' removed, total ' + b.total + ' (was ' + b.before + ').';
if (b.added_sample.length) msg += '\nAdded e.g.: ' + b.added_sample.join(', ');
if (b.removed_sample.length) msg += '\nRemoved e.g.: ' + b.removed_sample.join(', ');
if (!b.was_clean) msg += '\nAlso cleaned stray whitespace in the old value.';
if (b.guarded_major_providers.length) msg += '\nUpstream listed major providers, kept unblocked: ' + b.guarded_major_providers.join(', ');
if (b.invalid_skipped.length) msg += '\nSkipped invalid entries: ' + b.invalid_skipped.join(', ');
return [{ json: { verified: 1, total: b.total, added: b.added, removed: b.removed, message: msg } }];
